'use client';

import { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';

type GameStatus = { area: string; discovered: number };

function makeTree(scene: THREE.Scene, x: number, z: number, scale: number, variant: number) {
  const group = new THREE.Group();
  group.position.set(x, 0, z);
  group.scale.setScalar(scale);
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(.2, .34, 3.3, 7), new THREE.MeshStandardMaterial({ color: '#72533b', roughness: 1 }));
  trunk.position.y = 1.65;
  group.add(trunk);
  const colors = ['#527354', '#66815d', '#879064', '#516961'];
  for (let i = 0; i < 3; i++) {
    const crown = new THREE.Mesh(new THREE.IcosahedronGeometry(1.35 - i * .19, 1), new THREE.MeshStandardMaterial({ color: colors[(variant + i) % colors.length], roughness: .94, flatShading: true }));
    crown.position.set((i % 2 ? .3 : -.25), 3.1 + i * .67, (i - 1) * .13);
    crown.scale.set(1.05, 1.05, .94);
    crown.castShadow = true;
    group.add(crown);
  }
  scene.add(group);
}

function makeRock(scene: THREE.Scene, x: number, z: number, scale: number, color = '#777d71') {
  const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(scale, 0), new THREE.MeshStandardMaterial({ color, roughness: .92, flatShading: true }));
  rock.position.set(x, scale * .47, z);
  rock.rotation.set(.2, Math.random() * 2, .16);
  rock.scale.y = .65;
  rock.castShadow = true;
  rock.receiveShadow = true;
  scene.add(rock);
}

function makeFlower(scene: THREE.Scene, x: number, z: number, color: string) {
  const stem = new THREE.Mesh(new THREE.CylinderGeometry(.018, .028, .28, 5), new THREE.MeshStandardMaterial({ color: '#718b58' }));
  stem.position.set(x, .14, z);
  const bloom = new THREE.Mesh(new THREE.SphereGeometry(.075, 7, 6), new THREE.MeshBasicMaterial({ color }));
  bloom.position.set(x, .31, z);
  scene.add(stem, bloom);
}

function buildWorld(scene: THREE.Scene) {
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(360, 360, 90, 90), new THREE.MeshStandardMaterial({ color: '#7b896a', roughness: 1 }));
  ground.name = 'ground';
  ground.rotation.x = -Math.PI / 2;
  const pos = ground.geometry.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i);
    const hill = Math.max(0, Math.sin(x * .036 + 1.2) * Math.cos(y * .029) + Math.sin(y * .052) * .28);
    pos.setZ(i, hill * 3.2 + Math.sin(x * .09) * Math.cos(y * .07) * .26);
  }
  ground.geometry.computeVertexNormals();
  ground.receiveShadow = true;
  scene.add(ground);

  // The central meadow stays open for traversal; tree clusters create natural edges and sightlines.
  const rng = (n: number) => { const v = Math.sin(n * 127.1 + 311.7) * 43758.5453; return v - Math.floor(v); };
  for (let i = 0; i < 148; i++) {
    const angle = rng(i + 3) * Math.PI * 2;
    const radius = 17 + rng(i + 90) * 54;
    const x = Math.cos(angle) * radius;
    const z = Math.sin(angle) * radius;
    if (Math.abs(x) < 13 && Math.abs(z) < 15) continue;
    makeTree(scene, x, z, .72 + rng(i + 14) * .72, i % 4);
  }
  for (let i = 0; i < 58; i++) {
    const x = (rng(i + 200) - .5) * 95, z = (rng(i + 340) - .5) * 92;
    makeRock(scene, x, z, .32 + rng(i + 470) * .95, i % 3 === 0 ? '#817f73' : '#6d796b');
  }
  for (let i = 0; i < 175; i++) {
    const x = (rng(i + 880) - .5) * 32, z = (rng(i + 970) - .5) * 28;
    if (Math.abs(x) > 5 || Math.abs(z) > 4) makeFlower(scene, x, z, i % 5 ? '#e2c99a' : '#d6a7a0');
  }

  // A quiet, ancient waystone: a readable landmark and a promise of the world beyond.
  const stone = new THREE.Group();
  stone.position.set(0, 0, -11);
  const pillar = new THREE.Mesh(new THREE.BoxGeometry(1.35, 3.7, .85), new THREE.MeshStandardMaterial({ color: '#9a9781', roughness: .85 }));
  pillar.position.y = 1.85; pillar.rotation.z = -.045; pillar.castShadow = true;
  const cap = new THREE.Mesh(new THREE.ConeGeometry(1.04, .76, 4), new THREE.MeshStandardMaterial({ color: '#777a6d', roughness: 1 }));
  cap.position.y = 4.03; cap.rotation.y = Math.PI / 4;
  const glyph = new THREE.Mesh(new THREE.TorusGeometry(.25, .035, 8, 24), new THREE.MeshBasicMaterial({ color: '#dbc990' }));
  glyph.position.set(0, 2.45, .45);
  stone.add(pillar, cap, glyph); scene.add(stone);
  const path = new THREE.Mesh(new THREE.PlaneGeometry(5.3, 25), new THREE.MeshStandardMaterial({ color: '#9b8b6c', roughness: 1 }));
  path.rotation.x = -Math.PI / 2; path.position.set(0, .025, 2); scene.add(path);
}

function buildHero(scene: THREE.Scene) {
  const hero = new THREE.Group();
  const body = new THREE.Group(); hero.add(body);
  const cloth = new THREE.MeshStandardMaterial({ color: '#536b71', roughness: .8, flatShading: true });
  const pale = new THREE.MeshStandardMaterial({ color: '#d6c9a9', roughness: .9 });
  const dark = new THREE.MeshStandardMaterial({ color: '#393e42', roughness: .86 });
  const skin = new THREE.MeshStandardMaterial({ color: '#e6c5a8', roughness: .8 });
  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(.4, .67, 4, 8), cloth); torso.position.y = 1.35; torso.castShadow = true; body.add(torso);
  const coat = new THREE.Mesh(new THREE.ConeGeometry(.63, 1.1, 7, 1, true), pale); coat.position.set(0, .91, 0); coat.rotation.x = Math.PI; coat.castShadow = true; body.add(coat);
  const head = new THREE.Mesh(new THREE.SphereGeometry(.31, 12, 10), skin); head.position.y = 2.12; head.castShadow = true; body.add(head);
  const hair = new THREE.Mesh(new THREE.SphereGeometry(.34, 10, 8, 0, Math.PI * 2, 0, Math.PI * .63), new THREE.MeshStandardMaterial({ color: '#c3c5b7', roughness: .8 })); hair.position.set(0, 2.23, -.035); body.add(hair);
  const hat = new THREE.Mesh(new THREE.ConeGeometry(.57, .82, 9), new THREE.MeshStandardMaterial({ color: '#6a6558', roughness: .85 })); hat.position.y = 2.75; hat.rotation.z = -.08; hat.castShadow = true; body.add(hat);
  const brim = new THREE.Mesh(new THREE.CylinderGeometry(.55, .55, .08, 12), dark); brim.position.y = 2.42; body.add(brim);
  const legs: THREE.Mesh[] = [];
  const arms: THREE.Mesh[] = [];
  for (const side of [-1, 1]) {
    const leg = new THREE.Mesh(new THREE.CapsuleGeometry(.13, .52, 3, 6), dark); leg.position.set(side * .19, .43, 0); leg.castShadow = true; body.add(leg); legs.push(leg);
    const arm = new THREE.Mesh(new THREE.CapsuleGeometry(.105, .51, 3, 6), cloth); arm.position.set(side * .48, 1.38, 0); arm.castShadow = true; body.add(arm); arms.push(arm);
  }
  const staff = new THREE.Mesh(new THREE.CylinderGeometry(.035, .055, 2.25, 7), new THREE.MeshStandardMaterial({ color: '#755c43', roughness: .9 }));
  staff.position.set(.66, 1.02, .05); staff.rotation.z = -.045; body.add(staff);
  const orb = new THREE.Mesh(new THREE.IcosahedronGeometry(.15, 1), new THREE.MeshBasicMaterial({ color: '#e4d6a8' })); orb.position.set(.66, 2.2, .05); body.add(orb);
  const aura = new THREE.PointLight('#d6c99a', 1.1, 4); aura.position.copy(orb.position); body.add(aura);
  hero.userData = { body, legs, arms, orb };
  hero.position.set(0, 0, 2);
  scene.add(hero);
  return hero;
}

export default function Game() {
  const hostRef = useRef<HTMLDivElement>(null);
  const [status, setStatus] = useState<GameStatus>({ area: 'Campos da Aurora', discovered: 0 });
  const [hint, setHint] = useState('');
  const [nearLandmark, setNearLandmark] = useState(false);
  const [muted, setMuted] = useState(false);
  const [help, setHelp] = useState(false);
  const [questOpen, setQuestOpen] = useState(false);
  const uiOpenRef = useRef(false);
  uiOpenRef.current = help || questOpen;

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const scene = new THREE.Scene();
    scene.background = new THREE.Color('#9ba998');
    scene.fog = new THREE.FogExp2('#a7ad97', .0095);
    const camera = new THREE.PerspectiveCamera(48, 1, .1, 600);
    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.65));
    renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.08;
    host.appendChild(renderer.domElement);
    scene.add(new THREE.HemisphereLight('#e6e9d9', '#525b4c', 2.1));
    const sun = new THREE.DirectionalLight('#ffedc9', 2.8); sun.position.set(-34, 52, 24); sun.castShadow = true; sun.shadow.mapSize.set(1536, 1536); sun.shadow.camera.left = -65; sun.shadow.camera.right = 65; sun.shadow.camera.top = 65; sun.shadow.camera.bottom = -65; scene.add(sun);
    const fill = new THREE.DirectionalLight('#c3d1db', .75); fill.position.set(25, 20, -35); scene.add(fill);
    buildWorld(scene);
    const hero = buildHero(scene);
    const ground = scene.getObjectByName('ground') as THREE.Mesh;
    const raycaster = new THREE.Raycaster();
    let velocityY = 0;
    let isGrounded = false;
    const GRAVITY = -30;
    const JUMP_SPEED = 10;
    const keys = new Set<string>();
    let yaw = 0, pitch = .17, dragging = false, previousX = 0, previousY = 0, elapsed = 0, discovered = false, isNearLandmark = false, cameraDistance = 9.5;
    const target = new THREE.Vector3(0, 1.2, 0);
    const cameraOffset = new THREE.Vector3();
    const clock = new THREE.Clock();
    let hintTimer: ReturnType<typeof setTimeout> | undefined;
    const showHint = (message: string) => {
      setHint(message);
      if (hintTimer) clearTimeout(hintTimer);
      hintTimer = setTimeout(() => setHint(''), 3600);
    };
    const onKeyDown = (e: KeyboardEvent) => {
      const k = e.key.toLowerCase();
      if (['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','shift','escape','h','j','e'].includes(k)) e.preventDefault();
      if (e.repeat && ['h', 'j', 'e', ' '].includes(k)) return;
      keys.add(k);
      if (k === 'h') setHelp(v => !v);
      if (k === 'j') setQuestOpen(v => !v);
      if (k === 'e' && isNearLandmark) {
        if (!discovered) {
          discovered = true;
          setStatus({ area: 'Campos da Aurora', discovered: 1 });
          showHint('Voc\u00ea recordou o marco antigo.');
        } else {
          showHint('A pedra guarda um nome que o tempo j\u00e1 esqueceu.');
        }
      }
      if (k === 'escape' && document.pointerLockElement === renderer.domElement) document.exitPointerLock();
    };
    const onKeyUp = (e: KeyboardEvent) => keys.delete(e.key.toLowerCase());
    const onBlur = () => keys.clear();
    const onMouseDown = (e: MouseEvent) => {
      if (e.button === 0) {
        renderer.domElement.requestPointerLock();
        dragging = true;
        previousX = e.clientX;
        previousY = e.clientY;
      }
    };
    const onMouseMove = (e: MouseEvent) => {
      if (!dragging) return;
      const dx = document.pointerLockElement === renderer.domElement ? e.movementX : e.clientX - previousX;
      const dy = document.pointerLockElement === renderer.domElement ? e.movementY : e.clientY - previousY;
      yaw -= dx * .004;
      pitch = THREE.MathUtils.clamp(pitch + dy * .002, -.08, .7);
      previousX = e.clientX;
      previousY = e.clientY;
    };
    const onPointerLockChange = () => { dragging = document.pointerLockElement === renderer.domElement; };
    const onWheel = (e: WheelEvent) => { cameraDistance = THREE.MathUtils.clamp(cameraDistance + e.deltaY * .008, 5, 15); };
    const onContextMenu = (e: MouseEvent) => e.preventDefault();
    const onMouseUp = () => dragging = false;
    const onResize = () => { const w = host.clientWidth, h = host.clientHeight; if (!w || !h) return; renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix(); };
    onResize(); window.addEventListener('resize', onResize); window.addEventListener('keydown', onKeyDown); window.addEventListener('keyup', onKeyUp); window.addEventListener('blur', onBlur);
    renderer.domElement.addEventListener('mousedown', onMouseDown); renderer.domElement.addEventListener('wheel', onWheel, { passive: true }); renderer.domElement.addEventListener('contextmenu', onContextMenu);
    document.addEventListener('pointerlockchange', onPointerLockChange); window.addEventListener('mousemove', onMouseMove); window.addEventListener('mouseup', onMouseUp);
    let frame = 0;
    const animate = () => {
      frame = requestAnimationFrame(animate);
      const dt = Math.min(clock.getDelta(), .05);
      elapsed += dt;

      // Input handling
      const forward = uiOpenRef.current ? 0 : (keys.has('w') || keys.has('arrowup') ? 1 : 0) - (keys.has('s') || keys.has('arrowdown') ? 1 : 0);
      const side = uiOpenRef.current ? 0 : (keys.has('d') || keys.has('arrowright') ? 1 : 0) - (keys.has('a') || keys.has('arrowleft') ? 1 : 0);
      const moving = forward !== 0 || side !== 0;

      // Horizontal movement
      if (moving) {
        const direction = new THREE.Vector3(Math.sin(yaw), 0, Math.cos(yaw));
        const right = new THREE.Vector3(direction.z, 0, -direction.x);
        const move = direction.multiplyScalar(forward).add(right.multiplyScalar(side)).normalize();
        const sprint = keys.has('shift') ? 1.72 : 1;
        hero.position.addScaledVector(move, dt * 5 * sprint);
        hero.position.x = THREE.MathUtils.clamp(hero.position.x, -105, 105);
        hero.position.z = THREE.MathUtils.clamp(hero.position.z, -105, 105);
        hero.rotation.y = Math.atan2(move.x, move.z);
      }

      // Jump handling
      if (!uiOpenRef.current && keys.has(' ') && isGrounded) {
        velocityY = JUMP_SPEED;
        isGrounded = false;
      }

      // Gravity
      velocityY += GRAVITY * dt;
      hero.position.y += velocityY * dt;

      // Ground raycast (ignore hero)
      raycaster.set(new THREE.Vector3(hero.position.x, 50, hero.position.z), new THREE.Vector3(0, -1, 0));
      const hits = raycaster.intersectObject(ground, false);
      if (hits.length > 0) {
        const groundY = hits[0].point.y;
        if (hero.position.y < groundY) {
          hero.position.y = groundY;
          velocityY = 0;
          isGrounded = true;
        }
      }

      // Hero animation
      const { body, legs, arms, orb } = hero.userData as any;
      const stride = moving ? Math.sin(elapsed * (keys.has('shift') ? 15 : 10)) : 0;
      body.position.y = moving ? Math.abs(Math.sin(elapsed * 10)) * .055 : Math.sin(elapsed * 1.45) * .018;
      legs[0].rotation.x = stride * .48;
      legs[1].rotation.x = -stride * .48;
      arms[0].rotation.x = -stride * .25;
      arms[1].rotation.x = stride * .25;
      orb.scale.setScalar(.9 + Math.sin(elapsed * 1.8) * .08);

      // Landmark handling
      const dist = hero.position.distanceTo(new THREE.Vector3(0, 0, -11));
      const isNear = dist < 5;
      if (isNear !== isNearLandmark) {
        isNearLandmark = isNear;
        setNearLandmark(isNear);
      }

      // Camera positioning with obstacle avoidance
      target.set(hero.position.x, hero.position.y + 1.25, hero.position.z);
      cameraOffset.set(
        Math.sin(yaw) * Math.cos(pitch),
        Math.sin(pitch) + .25,
        Math.cos(yaw) * Math.cos(pitch)
      ).multiplyScalar(cameraDistance);
      const desiredPos = target.clone().add(cameraOffset);
      raycaster.set(target, cameraOffset.clone().normalize());
      const camHits = raycaster.intersectObjects(scene.children, true)
        .filter(hit => hit.object !== hero && hit.object !== ground);
      if (camHits.length > 0 && camHits[0].distance < cameraOffset.length()) {
        const safeDist = Math.max(2.5, camHits[0].distance - 0.3);
        camera.position.copy(target.clone().add(cameraOffset.clone().setLength(safeDist)));
      } else {
        camera.position.lerp(desiredPos, 1 - Math.pow(.001, dt));
      }
      camera.lookAt(target);

      renderer.render(scene, camera);
    };



    animate();
    return () => {
      cancelAnimationFrame(frame); if (hintTimer) clearTimeout(hintTimer);
      window.removeEventListener('resize', onResize); window.removeEventListener('keydown', onKeyDown); window.removeEventListener('keyup', onKeyUp); window.removeEventListener('blur', onBlur); window.removeEventListener('mousemove', onMouseMove); window.removeEventListener('mouseup', onMouseUp);
      document.removeEventListener('pointerlockchange', onPointerLockChange);
      renderer.domElement.removeEventListener('mousedown', onMouseDown); renderer.domElement.removeEventListener('wheel', onWheel); renderer.domElement.removeEventListener('contextmenu', onContextMenu);
      if (document.pointerLockElement === renderer.domElement) document.exitPointerLock();
      renderer.dispose(); scene.traverse(obj => { if (obj instanceof THREE.Mesh) { obj.geometry.dispose(); const mats = Array.isArray(obj.material) ? obj.material : [obj.material]; mats.forEach(m => m.dispose()); } });
      host.removeChild(renderer.domElement);
    };
  }, []);

  return <main className="game-shell">
    <div className="scene" ref={hostRef} aria-label="Mundo 3D explorável dos Campos da Aurora" />
    <div className="vignette" />
    <header className="topbar">
      <div className="brand"><div className="brand-mark">✧</div><div><div className="eyebrow">UM MUNDO DEPOIS DO FIM</div><div className="brand-name">ECOS <span>DA ERA DOS HERÓIS</span></div></div></div>
      <div className="region"><span className="region-dot" />{status.area}<div className="region-sub">Oeste · Terras de Avel</div></div>
      <div className="top-actions"><button className="icon-button" onClick={() => setMuted(v => !v)} aria-label={muted ? 'Ativar som' : 'Silenciar'} title={muted ? 'Ativar som' : 'Silenciar'}>{muted ? '◖' : '♫'}</button><button className="icon-button" onClick={() => setHelp(v => !v)} aria-label="Ajuda" title="Controles">?</button></div>
    </header>
    <section className="quest-card"><div className="quest-kicker"><span className="tiny-star">✦</span> MEMÓRIA ESQUECIDA</div><h1>O que permanece</h1><p>Encontre o antigo marco no coração do campo.</p><div className="quest-progress"><span style={{ width: `${status.discovered * 100}%` }} /></div><div className="quest-count">{status.discovered ? '1' : '0'} <span>/ 1 marco descoberto</span></div></section>
    <div className="compass"><div className="compass-ring"><span className="compass-n">N</span><span className="compass-needle">◆</span><span className="compass-pin">✦</span><span className="compass-s">S</span></div><div className="compass-label">CAMPOS DA AURORA</div></div>
    <div className="bottom-left"><div className="player-card"><div className="portrait">✧</div><div className="player-meta"><strong>Viajante</strong><span>Errante das Terras de Avel</span></div><div className="level">✦</div></div></div>
    <div className="bottom-center">{nearLandmark && <div className="interaction"><span className="keycap">E</span><span>Recordar o marco</span></div>}<div className="hotbar"><div className="hotkey"><span className="slot">J</span><span className="slot-label">Jornada</span></div><div className="hotkey"><span className="slot">H</span><span className="slot-label">Ajuda</span></div></div></div>
    <div className="bottom-right"><div className="world-time"><span>◷</span> AMANHECER</div><div className="weather">PRÓLOGO · CAMPOS DA AURORA</div></div>
    {hint && <div className="toast"><span>✧</span>{hint}</div>}
    {help && <div className="modal-backdrop" onClick={() => setHelp(false)}><div className="modal" onClick={e => e.stopPropagation()}><button className="modal-close" onClick={() => setHelp(false)}>×</button><span className="modal-kicker">CAMINHOS DO VIAJANTE</span><h2>Um passo de cada vez.</h2><p>Os caminhos ainda estão quietos. Explore o campo e encontre as memórias que resistiram ao tempo.</p><div className="controls-grid"><div><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd><span>Mover</span></div><div><kbd>Mouse</kbd><span>Olhar ao redor</span></div><div><kbd>Shift</kbd><span>Correr</span></div><div><kbd>E</kbd><span>Recordar junto ao marco</span></div><div><kbd>J</kbd><span>Jornada</span></div><div><kbd>H</kbd><span>Controles</span></div></div><button className="continue" onClick={() => setHelp(false)}>CONTINUAR A JORNADA <span>→</span></button></div></div>}
    {questOpen && <div className="modal-backdrop" onClick={() => setQuestOpen(false)}><div className="modal quest-modal" onClick={e => e.stopPropagation()}><button className="modal-close" onClick={() => setQuestOpen(false)}>×</button><span className="modal-kicker">DIÁRIO DE VIAGEM · 01</span><h2>O que permanece</h2><p>Quase mil anos se passaram desde a queda de Valkhor. A relva tomou os velhos caminhos, e os nomes dos heróis já não são lembrados.</p><p>Um marco de pedra repousa ao norte, coberto de musgo. Talvez ainda guarde uma lembrança.</p><div className="quest-objective"><span>✦</span>{status.discovered ? 'Marco antigo descoberto' : 'Encontre o antigo marco'}</div></div></div>}
    <div className="build-stamp">PRÓLOGO <span>·</span> VERSÃO 0.1</div>
  </main>;
}
